// Writes the free sample PDFs linked from the marketing pages: node tools/make-samples.mjs [--check] [--only <name>]
//
// Dogfooding (SPEC §7): each sample is a real book made by the shipped code, exactly as the Studio's free edition
// exports it. Projects come from the Studio templates (site/js/ui/templates.js), every puzzle is generated by the
// engines with a fixed seed and checked with the engine's own verify(), layoutBook() runs with pro:false (so every
// page carries the free proof header and footer), preflight() must report nothing but the expected free-proof
// "watermark" error, and site/js/render/pdf-backend.js builds the file through the vendored jsPDF, the same code
// path as the in-browser export. Each book has its real front matter (title, copyright, "belongs to", how to
// solve, contents where the template has one), the answer key and back matter, at exactly the page count in its
// file name, with no padding pages.
//
// Output is byte-for-byte reproducible: jsPDF's two volatile fields (CreationDate and the file /ID) are rewritten
// in place with a fixed date and a content hash of the same length, so the xref offsets stay valid.
//
//   --check        rebuild in memory and compare with the files on disk (exit code 1 if any differs or is missing)
//   --only <name>  build just one sample (e.g. --only sudoku-sampler-24p)
//
// After writing, if poppler-utils is installed, each file is checked with pdfinfo (page count and size), pdffonts
// (every font embedded) and pdftotext (the free footer is on every page). tools/test/assets.test.mjs runs the
// same checks on the committed files.
//
// The proof footer prints CONFIG.printDomain (site/config.js): after changing the domain there, run this script
// (and tools/make-og.mjs) again; the assets test fails until you do.
//
// Files (site/samples/):
//   picture-logic-32p.pdf             "Try the 32-page sample" (SPEC 4.4): Picture Logic template, 8.5 x 11 in
//   large-print-word-search-24p.pdf   Large Print Word Search template, 8.5 x 11 in, 18pt+ letters
//   sudoku-sampler-24p.pdf            Sudoku Easy to Expert template, 6 x 9 in, two per page, all four grades
import { createRequire } from 'node:module';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { CONFIG } from '../site/config.js';
import { FONT_DATA } from '../site/js/core/fontmetrics-data.js';
import '../site/js/render/pdf-backend.js';
import { buildFromTemplate } from '../site/js/ui/templates.js';
import { normalizeProject } from '../site/js/core/project.js';
import { runJob } from '../site/js/puzzles/generate.js';
import { getType } from '../site/js/puzzles/registry.js';
import { puzzleSeed } from '../site/js/core/rng.js';
import { layoutBook, watermarkText } from '../site/js/layout/book.js';
import { preflight } from '../site/js/kdp/preflight.js';

const require = createRequire(import.meta.url);
const SITE = fileURLToPath(new URL('../site/', import.meta.url));
export const OUT = join(SITE, 'samples');
const { jsPDF } = require(join(SITE, 'vendor/jspdf-4.2.1.umd.min.js'));

/** Fixed PDF creation date (the day the samples were first made), written in jsPDF's own D:…±HH'mm' format. */
const PDF_DATE = "D:20261109000000+00'00'";
const AUTHOR = 'Gridbook Studio';
const YEAR = 2026;
const GEN_DEADLINE_MS = 120000; // generous, so a slow machine never turns a puzzle into a timeout

/** Copyright page for a sample: the normal notice plus one honest line about what a free export is. */
function sampleCopyright(title) {
  return [
    title,
    '',
    `Copyright ©${YEAR} ${AUTHOR}. All rights reserved.`,
    '',
    `This is a free sample made with the free edition of Gridbook Studio (${CONFIG.printDomain}). `
      + 'Free exports carry a proof header and footer on every page, like this one. '
      + 'Pro exports of the same book have no proof marks.',
    '',
    'You may print this sample and photocopy the puzzle pages for your own personal or classroom use.',
  ].join('\n');
}

/** Give a template project fixed ids, seed and date, so its puzzles are the same on every run. */
export function pinProject(project, { key, title, subtitle, counts }) {
  const p = structuredClone(project);
  p.id = `sample-${key}`;
  p.seed = `gridbook-sample-${key}-v1`;
  if (title) p.title = title;
  if (subtitle) p.subtitle = subtitle;
  p.author = AUTHOR;
  p.year = YEAR;
  p.createdAt = p.updatedAt = '2026-11-09T00:00:00Z';
  p.copyrightText = sampleCopyright(p.title);
  p.sections.forEach((s, i) => {
    s.id = `s${i + 1}`;
    if (counts) s.count = counts[i];
  });
  return normalizeProject(p);
}

/**
 * The three samples. `project()` returns the pinned project; `pages` is the exact page count promised by the file
 * name and the links on the marketing pages.
 */
export const SAMPLES = [
  {
    file: 'picture-logic-32p.pdf', pages: 32,
    subject: 'Free 32-page sample: picture logic puzzles (nonograms) with answer key, made with Gridbook Studio',
    project: () => {
      // The Studio's own "Try the 32-page sample" book (templates.js sizes it to exactly 32 pages).
      const t = buildFromTemplate('picture-logic', { sample: true });
      return pinProject(t, { key: 'picture-logic' });
    },
  },
  {
    file: 'large-print-word-search-24p.pdf', pages: 24,
    subject: 'Free 24-page sample: large print word search puzzles with answer key, made with Gridbook Studio',
    project: () => pinProject(buildFromTemplate('large-print-wordsearch'), {
      key: 'large-print-word-search', counts: [14], subtitle: '14 Puzzles for Adults',
    }),
  },
  {
    file: 'sudoku-sampler-24p.pdf', pages: 24,
    subject: 'Free 24-page sample: sudoku from Easy to Expert with answer key, made with Gridbook Studio',
    project: () => pinProject(buildFromTemplate('sudoku-easy-expert'), {
      key: 'sudoku-sampler', counts: [6, 4, 4, 4], title: 'Sudoku Sampler', subtitle: 'Easy to Expert: 18 Puzzles in Four Levels',
    }),
  },
];

/** Generate every puzzle of a project on this thread (the job runner the worker pool uses), verified. */
export function generateAll(project) {
  const puzzles = {};
  for (const s of project.sections) {
    const engine = getType(s.type);
    puzzles[s.id] = [];
    for (let i = 0; i < s.count; i++) {
      const seed = puzzleSeed(project.seed, s, i);
      const r = runJob(getType, { type: s.type, opts: s.opts, seed, index: i, count: s.count, deadlineMs: GEN_DEADLINE_MS });
      if (!r.puzzle) throw new Error(`${project.title}: ${s.type} puzzle ${i + 1} failed: ${r.error}`);
      const v = engine.verify(r.puzzle);
      if (!v.ok) throw new Error(`${project.title}: ${s.type} puzzle ${i + 1} failed verify(): ${v.reason}`);
      puzzles[s.id].push(r.puzzle);
    }
  }
  return puzzles;
}

let fontsCache = null;
function fonts() {
  if (!fontsCache) {
    fontsCache = {
      regular: readFileSync(join(SITE, 'fonts/AtkinsonHyperlegible-Regular.ttf')).toString('base64'),
      bold: readFileSync(join(SITE, 'fonts/AtkinsonHyperlegible-Bold.ttf')).toString('base64'),
    };
  }
  return fontsCache;
}

/**
 * Replace jsPDF's CreationDate and random file /ID with fixed-length deterministic values (offsets unchanged).
 * @param {Uint8Array} bytes
 */
export function stabilizePdf(bytes) {
  let s = Buffer.from(bytes).toString('latin1');
  const date = /\/CreationDate \((D:[^)]*)\)/;
  const m = date.exec(s);
  if (!m) throw new Error('stabilizePdf: no /CreationDate in the PDF');
  if (m[1].length !== PDF_DATE.length) throw new Error(`stabilizePdf: unexpected date format ${m[1]}`);
  s = s.replace(date, `/CreationDate (${PDF_DATE})`);
  const id = /\/ID \[ <([0-9A-F]{32})> <([0-9A-F]{32})> \]/;
  if (!id.test(s)) throw new Error('stabilizePdf: no file /ID in the PDF');
  const zero = '0'.repeat(32);
  s = s.replace(id, `/ID [ <${zero}> <${zero}> ]`);
  const hash = createHash('md5').update(Buffer.from(s, 'latin1')).digest('hex').toUpperCase();
  s = s.replace(`/ID [ <${zero}> <${zero}> ]`, `/ID [ <${hash}> <${hash}> ]`);
  const out = Buffer.from(s, 'latin1');
  if (out.length !== bytes.byteLength) throw new Error('stabilizePdf: length changed');
  return out;
}

/**
 * Generate and lay out one sample (no PDF): the pinned project, its verified puzzles, the free-edition layout and
 * its preflight. Throws if the page count, padding, proof marks or preflight are not exactly as promised.
 * @returns {{ project: object, puzzles: object, book: object, pf: object }}
 */
export function layoutSample(sample) {
  const project = sample.project();
  const puzzles = generateAll(project);
  const book = layoutBook(project, puzzles, { pro: false });
  const { meta } = book;
  if (meta.pageCount !== sample.pages) {
    throw new Error(`${sample.file}: layout has ${meta.pageCount} pages, the file name promises ${sample.pages}`);
  }
  if (meta.paddedPages) throw new Error(`${sample.file}: ${meta.paddedPages} padding page(s); adjust the puzzle counts`);
  if (!meta.watermarked) throw new Error(`${sample.file}: a free sample must carry the free proof marks`);
  const pf = preflight(project, book, puzzles, { pro: false });
  const unexpected = pf.errors.filter((e) => e.code !== 'watermark');
  if (unexpected.length) throw new Error(`${sample.file}: preflight errors: ${unexpected.map((e) => `${e.code}: ${e.msg}`).join(' | ')}`);
  if (!pf.errors.some((e) => e.code === 'watermark')) throw new Error(`${sample.file}: preflight did not see the free proof marks`);
  if (pf.warnings.length) throw new Error(`${sample.file}: preflight warnings: ${pf.warnings.map((w) => `${w.code}: ${w.msg}`).join(' | ')}`);
  return { project, puzzles, book, pf };
}

/**
 * Build one sample in memory.
 * @returns {{ buf: Buffer, project: object, puzzles: object, book: object, pf: object }}
 */
export function buildSample(sample) {
  const { project, puzzles, book, pf } = layoutSample(sample);
  const types = [...new Set(project.sections.map((s) => getType(s.type).meta.name.toLowerCase()))];
  const raw = globalThis.GBSPdfBackend.buildPdf(jsPDF, book.pages, fonts(), {
    title: `${project.title} (free sample)`,
    author: AUTHOR,
    subject: sample.subject,
    keywords: ['puzzle book', 'free sample', ...types].join(', '),
    metrics: FONT_DATA,
  });
  return { buf: stabilizePdf(new Uint8Array(raw)), project, puzzles, book, pf };
}

// ------------------------------------------------------------------ poppler checks (optional)

function hasTool(cmd) {
  try { execFileSync(cmd, ['-v'], { stdio: 'ignore' }); return true; } catch (e) { return e.code !== 'ENOENT'; }
}

/**
 * Check a written PDF with poppler: page count and size, every font embedded, the free footer on every page.
 * Returns a list of problems (empty = fine), or null when poppler-utils is not installed.
 */
export function popplerCheck(file, { pages, pageW, pageH }) {
  if (!hasTool('pdfinfo') || !hasTool('pdffonts') || !hasTool('pdftotext')) return null;
  const problems = [];
  const info = execFileSync('pdfinfo', [file], { encoding: 'utf8' });
  const n = Number(/^Pages:\s+(\d+)/m.exec(info)?.[1]);
  if (n !== pages) problems.push(`pdfinfo: ${n} pages, expected ${pages}`);
  const size = /^Page size:\s+([\d.]+) x ([\d.]+) pts/m.exec(info);
  if (!size || Math.abs(Number(size[1]) - pageW) > 0.01 || Math.abs(Number(size[2]) - pageH) > 0.01) {
    problems.push(`pdfinfo: page size ${size ? `${size[1]} x ${size[2]}` : '?'} pt, expected ${pageW} x ${pageH}`);
  }
  const fontRows = execFileSync('pdffonts', [file], { encoding: 'utf8' }).trim().split('\n').slice(2).filter(Boolean);
  if (!fontRows.length) problems.push('pdffonts: no fonts');
  for (const row of fontRows) {
    const cols = row.trim().split(/\s+/);
    // name type... encoding emb sub uni object ID: emb is the 5th field from the end.
    if (cols[cols.length - 5] !== 'yes') problems.push(`pdffonts: not embedded: ${row}`);
    if (!/^[A-Z]{6}\+AtkinsonHyperlegible-(Regular|Bold)$/.test(cols[0])) problems.push(`pdffonts: unexpected font ${cols[0]}`);
  }
  const text = execFileSync('pdftotext', ['-layout', file, '-'], { encoding: 'utf8' });
  const perPage = text.split('\f').slice(0, pages);
  const wm = watermarkText();
  const missing = perPage.map((t, i) => (t.includes(wm.bottom) && t.includes(wm.top) ? 0 : i + 1)).filter(Boolean);
  if (missing.length) problems.push(`pdftotext: free footer/header missing on page(s) ${missing.join(', ')}`);
  return problems;
}

// ------------------------------------------------------------------ main

function main() {
  const args = process.argv.slice(2);
  const check = args.includes('--check');
  const only = args.includes('--only') ? args[args.indexOf('--only') + 1] : null;
  const list = only ? SAMPLES.filter((s) => s.file === only || s.file === `${only}.pdf`) : SAMPLES;
  if (!list.length) {
    console.error(`No sample named "${only}". Known: ${SAMPLES.map((s) => s.file).join(', ')}`);
    process.exit(2);
  }
  let failed = false;
  if (!check) mkdirSync(OUT, { recursive: true });
  for (const sample of list) {
    const t0 = performance.now();
    const { buf, book } = buildSample(sample);
    const path = join(OUT, sample.file);
    if (check) {
      const same = existsSync(path) && Buffer.compare(readFileSync(path), buf) === 0;
      console.log(`  ${sample.file.padEnd(34)} ${same ? 'up to date' : 'STALE'}`);
      if (!same) failed = true;
      continue;
    }
    writeFileSync(path, buf);
    const ms = Math.round(performance.now() - t0);
    console.log(`  ${sample.file.padEnd(34)} ${book.meta.pageCount} pages  ${book.meta.trimLabel}  ${(buf.length / 1024).toFixed(0)} KB  (${ms} ms)`);
    if (buf.length > 1.5 * 1024 * 1024) { console.error('    too large: keep samples under 1.5 MB'); failed = true; }
    const problems = popplerCheck(path, { pages: sample.pages, pageW: book.meta.pageW, pageH: book.meta.pageH });
    if (problems === null) console.log('    (poppler-utils not installed: skipped pdfinfo/pdffonts/pdftotext checks)');
    else if (problems.length) { failed = true; for (const p of problems) console.error(`    ${p}`); }
    else console.log('    pdfinfo, pdffonts, pdftotext: ok (fonts embedded, proof marks on every page)');
  }
  if (check && failed) console.error('Samples are stale. Run node tools/make-samples.mjs');
  if (failed) process.exit(1);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main();
